// 冒泡排序算法
function bubbleSort(arr) {
    const n = arr.length;

    for (let i = 0; i < n; i++) {
        let swapped = false;

        for (let j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
                swapped = true;
            }
        }

        if (!swapped) break;
    }

    return arr;
}

// 测试冒泡排序
const numbers = [64, 34, 25, 12, 22, 11, 90];
console.log(`排序前: ${numbers}`);
const sorted = bubbleSort([...numbers]);
console.log(`排序后: ${sorted}`);
